import { SelectedVal } from "../SelectedVal";
import { HTMLComponent } from "../HtmlComponent";
import LoadingSpinner from "./LoadingSpinner";
import { DataFactory, Literal } from "rdf-data-factory";
import { Term } from "@rdfjs/types/data-model";
import { RDFTerm, LabelledCriteria, Criteria, RdfTermCriteria } from "../../SparnaturalQueryIfc";
import { RdfTermDatasourceItem, SinglePredicateDataProviderIfc } from "../datasources/DataProviders";
import { getSettings } from "../../settings/defaultSettings";

const factory = new DataFactory();

// The ValueType decides wheter a widget has the possibility to choose only one value or multiple values
// example for multiples: List of countries in ListWidget
// example for single: Search string in SearchWidget
export enum ValueRepetition {
  SINGLE, // only one value can be chosen.
  MULTIPLE, // multiple values can be selected like a list of values
}

let RDFTermFactory = (term: Term): RDFTerm => {
  return {
    type: term.termType === "Literal" ? "literal" : term.termType === "BlankNode" ? "bnode" : "uri",
    value: term.value,
    "xml:lang": term instanceof Literal ? (term as Literal).language : undefined,
    datatype: term instanceof Literal ? (term as Literal).datatype.value : undefined, 
  }
}

export abstract class AbstractWidget extends HTMLComponent {
  public valueRepetition: ValueRepetition;
  startClassVal: SelectedVal;
  objectPropVal: SelectedVal;
  endClassVal: SelectedVal;
  protected blockStartTriple = false;
  protected blockObjectPropTriple = false;
  protected blockEndTriple = false;
  protected spinner = new LoadingSpinner(this).render();

  // registered once on the root component, see reloadOnQueryChange
  private queryChangeListener: () => void;

  // render() rebuilds the html, so the reload of the last render is the one to call
  private queryChangeReload: () => void;

  // pending reload, so that several queryUpdated in a row trigger a single one
  private reloadTimer: ReturnType<typeof setTimeout>;

  constructor(
    baseCssClass: string,
    parentComponent: HTMLComponent,
    widgetHTML: JQuery<HTMLElement>,
    startClassVal: SelectedVal,
    objectPropVal: SelectedVal,
    endClassVal: SelectedVal,
    valueRepetition: ValueRepetition
  ) {
    super(baseCssClass, parentComponent, widgetHTML);
    this.startClassVal = startClassVal;
    this.objectPropVal = objectPropVal;
    this.endClassVal = endClassVal;
    this.valueRepetition = valueRepetition;
  }

  render(): this {
    super.render();
    this.spinner.render();
    return this;
  }

  /**
   * Calls reload whenever the query changes, so that the widget keeps proposing only values
   * consistent with the filters set on the other lines.
   *
   * A widget is only displayed while its line has no value yet, so a reload never
   * discards a choice already made by the user.
   */
  protected reloadOnQueryChange(reload: () => void) {
    // nothing to reload when the datasources are not filtered by the query
    if (!getSettings().facetedBrowsing) return;

    this.queryChangeReload = reload;

    // render() may be called several times on the same widget, register only once
    if (this.queryChangeListener) return;

    // kept so that the listener can remove itself from the very same element
    const root = this.getRootComponent().html[0];

    this.queryChangeListener = () => {
      // the widget is taken off the page as soon as its line gets a value : there is
      // nothing left to reload, and nothing left to listen for
      if (!this.html[0]?.isConnected) {
        clearTimeout(this.reloadTimer);
        root.removeEventListener("queryUpdated", this.queryChangeListener);
        this.queryChangeListener = null;
        return;
      }

      // queryUpdated fires several times for a single user action, only keep the last
      clearTimeout(this.reloadTimer);
      this.reloadTimer = setTimeout(() => this.queryChangeReload(), 150);
    };

    root.addEventListener("queryUpdated", this.queryChangeListener);
  }

  // Is used to parse the inputs from the ISparnaturalJson e.g "preloaded" queries
  abstract parseInput(value: LabelledCriteria<Criteria>): LabelledCriteria<Criteria>;

  // Label of a criteria, from the criteria only (no DOM). Overridden per widget.
  getValueLabel(criteria: Criteria): string {
    return "";
  }

  // Builds { label, criteria } from a criteria (used to prefill a widget).
  buildValueFromCriteria<T extends Criteria>(criteria: T): LabelledCriteria<T> {
    return {
      label: this.getValueLabel(criteria),
      criteria: criteria,
    };
  }

  // Parses a raw string (e.g. URL param) into this widget's criteria. Base is
  // free-text search ; URI widgets go through resolveLabel() instead.
  parseRawValue(raw: string): Criteria {
    return { search: raw };
  }

  // True if this widget's values are URIs to be resolved against the endpoint.
  // Based on the resolver injected by the WidgetFactory, not on the value shape.
  protected holdsUriValues(): boolean {
    return !!this.labelResolver?.predicate;
  }

  // Builds { label, criteria } from a raw string (e.g. a URL param). Async
  // because URI widgets resolve their label via SPARQL : callers never have to
  // know whether this widget holds URIs or literals.
  buildValueFromRawValue(
    raw: string,
    callback: (value: LabelledCriteria<Criteria>) => void,
    errorCallback?: (payload: any) => void
  ): void {
    if (this.holdsUriValues()) {
      this.resolveLabel(
        raw,
        // Nothing resolved : fall back to the URI as its own label.
        (value) =>
          callback(
            value ?? {
              label: raw,
              criteria: { rdfTerm: { type: "uri", value: raw } },
            }
          ),
        errorCallback
      );
      return;
    }

    try {
      callback(this.buildValueFromCriteria(this.parseRawValue(raw)));
    } catch (e) {
      if (!errorCallback) throw e;
      errorCallback(e);
    }
  }

  // Splits a "min|max" range on the pipe (empty when a bound is missing).
  protected splitRawRange(raw: string): { first: string; second: string } {
    let parts = (raw ?? "").split("|");
    return {
      first: (parts[0] ?? "").trim(),
      second: (parts[1] ?? "").trim(),
    };
  }

  // URI label resolver, injected by the WidgetFactory (predicate undefined =
  // nothing to resolve).
  protected labelResolver?: {
    dataProvider: SinglePredicateDataProviderIfc;
    predicate: string | undefined;
  };

  // Injects the URI label resolver (called by the WidgetFactory).
  setLabelResolver(
    dataProvider: SinglePredicateDataProviderIfc,
    predicate: string | undefined
  ): void {
    this.labelResolver = { dataProvider, predicate };
  }

  // Resolves a URI's label via SPARQL, calling back with { label, criteria } or
  // undefined (no resolver/predicate/result - caller falls back to the URI).
  resolveLabel(
    uri: string,
    callback: (value: LabelledCriteria<RdfTermCriteria> | undefined) => void,
    errorCallback?: (payload: any) => void
  ): void {
    if (!this.labelResolver || !this.labelResolver.predicate) {
      callback(undefined);
      return;
    }

    this.labelResolver.dataProvider.getSinglePredicate(
      uri,
      this.labelResolver.predicate,
      (items: RdfTermDatasourceItem[]) => {
        if (items.length > 0 && items[0].label) {
          callback({
            label: items[0].label,
            criteria: { rdfTerm: { type: "uri", value: uri } },
          });
        } else {
          callback(undefined);
        }
      },
      errorCallback
    );
  }

  // fires the event to render the label of the WidgetValue on the UI
  // can take either a single value or an array of values
  triggerRenderWidgetVal(widgetValue: LabelledCriteria<Criteria> | LabelledCriteria<Criteria>[]) {
    this.html[0].dispatchEvent(
      new CustomEvent("renderWidgetVal", {
        bubbles: true,
        detail: widgetValue,
      })
    );
  }

  // Method to disable the widget
  disableWidget() {
    // Add a 'disabled-widget' class to visually indicate it's disabled
    //this.html[0].classList.add("disabled-widget");

    // Disable all input elements within the widget's HTML container
    const inputs = this.html[0].querySelectorAll(
      "input, button, select, textarea"
    );
    inputs.forEach((element) => {
      element.setAttribute("disabled", "true");
    });
  }

  // Method to enable the widget
  enableWidget() {
    // Remove the 'disabled-widget' class to restore normal appearance
    //this.html[0].classList.remove("disabled-widget");

    // Enable all input elements within the widget's HTML container
    const inputs = this.html[0].querySelectorAll(
      "input, button, select, textarea"
    );
    inputs.forEach((element) => {
      element.removeAttribute("disabled");
    });
  }

  // toggle spinner component when loading a datasource. show forces the state : a toggle gets out of
  // step when a load is replaced by a newer one before its answer
  toggleSpinner(message?: string, show?: boolean) {
    const elements = this.spinner.html[0].getElementsByClassName("load");
    if (elements.length > 0) elements[0].classList.toggle("show", show);
    if (message != null) this.spinner.renderMessage(message);
    // next frame : the widget may not be in the page yet
    requestAnimationFrame(() => this.#fitSpinner());
  }

  // zoom : no room on the right of the widget, the spinner and its message go inside it, empty while loading
  #fitSpinner() {
    const spinner = this.spinner.html[0];
    spinner.classList.remove("inside");
    const list = spinner.closest(".componentsListe");
    if (list && spinner.getBoundingClientRect().right > list.getBoundingClientRect().right) {
      spinner.classList.add("inside");
    }
  }
}
export { RDFTerm };

