import { getSettings } from "../../sparnatural/settings/defaultSettings";
import { ISparnaturalSpecification } from "../spec-providers/ISparnaturalSpecification";
import BgWrapper from "./builder-section/BgWrapper";
import SubmitSection from "./submit-section/SubmitSection";
import { SparnaturalSpecificationFactory } from "../spec-providers/SparnaturalSpecificationFactory";
import ActionStore from "../statehandling/ActionStore";
import VariableSection from "./variables-section/VariableSelection";
import { HTMLComponent } from "./HtmlComponent";
import { SparnaturalElement } from "../../SparnaturalElement";
import { I18n } from "../settings/I18n";
import { Catalog, Model } from "rdf-shacl-commons";
import CriteriaGroup from "./builder-section/groupwrapper/criteriagroup/CriteriaGroup";
import EndClassGroup from "./builder-section/groupwrapper/criteriagroup/startendclassgroup/EndClassGroup";
import StartClassGroup from "./builder-section/groupwrapper/criteriagroup/startendclassgroup/StartClassGroup";

class SparnaturalComponent extends HTMLComponent {
  specProvider: ISparnaturalSpecification;
  actionStore: ActionStore;
  BgWrapper: BgWrapper;
  submitSection: SubmitSection;
  variableSection: VariableSection;
  catalog?: Catalog;
  // filter that is applied to optional/not exists green arrows, based on its ID
  filter = $(
    '<svg data-name="Calque 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 0 0" style="width:0;height:0;display:block"><defs><filter style="color-interpolation-filters:sRGB;" inkscape:label="Drop Shadow" id="filter19278" x="-0.15483875" y="-0.11428573" width="1.3096775" height="1.2714286"><feFlood flood-opacity="0.811765" flood-color="rgb(120,120,120)" result="flood" id="feFlood19268" /><feComposite in="flood" in2="SourceGraphic" operator="out" result="composite1" id="feComposite19270" /><feGaussianBlur in="composite1" stdDeviation="2" result="blur" id="feGaussianBlur19272" /><feOffset dx="3.60822e-16" dy="1.8" result="offset" id="feOffset19274" /><feComposite in="offset" in2="SourceGraphic" operator="atop" result="composite2" id="feComposite19276" /></filter></defs></svg>'
  );

  // screen readers : read the messages written here, see HTMLComponent.announce()
  liveRegion: JQuery<HTMLElement>;

  constructor() {
    //Sparnatural: Does not have a ParentComponent!
    super("Sparnatural", null, null);
  }

  // hidden on screen but read, like the "sr-only" CSS class
  #renderLiveRegion() {
    this.liveRegion = $(
      `<div role="status" aria-live="polite" style="position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0"></div>`
    );
    this.html.append(this.liveRegion);
    // the same function each time : it is added only once, even if Sparnatural is rendered again
    this.html[0].addEventListener("announce", this.#onAnnounce);
  }

  // messages sent at the same time are read together, e.g. the end class and the property chosen with it
  #pendingMessages: string[] = [];
  #onAnnounce = (e: CustomEvent) => {
    this.#pendingMessages.push(e.detail);
    if (this.#pendingMessages.length > 1) return;
    // emptied first, so that the same message is read again
    this.liveRegion.text("");
    setTimeout(() => {
      this.liveRegion.text(this.#pendingMessages.join(". "));
      this.#pendingMessages = [];
    }, 100);
  };

  render(): this {
    this.#initLang();

    let afterSpecificationLoaded = (sp: ISparnaturalSpecification) => {
      this.specProvider = sp;
      this.actionStore = new ActionStore(this, this.specProvider);
      this.BgWrapper = new BgWrapper(this, this.specProvider).render();
      // display the submit button only if a callback was provided
      if (getSettings().submitButton) {
        this.submitSection = new SubmitSection(this).render();
      }
      this.variableSection = new VariableSection(
        this,
        this.specProvider
      ).render();
      //BGWrapper must be rendered first
      this.html[0].dispatchEvent(
        new CustomEvent("redrawBackgroundAndLinks", { bubbles: true })
      );

      // add resize listener
      let resizeTimeout: number;
      window.addEventListener('resize', () => {
        clearTimeout(resizeTimeout);
        resizeTimeout = window.setTimeout(() => {
          this.html[0].dispatchEvent(
            new CustomEvent("redrawBackgroundAndLinks", { bubbles: true })
          );
        }, 150);
      });

      this.html.append(this.filter);
      this.#renderLiveRegion();
      console.log(
        "Found languages in configuration : " + this.specProvider.getLanguages()
      );

      this.html[0].dispatchEvent(
        new CustomEvent(SparnaturalElement.EVENT_INIT, {
          bubbles: true,
          detail: {
            sparnatural: this,
            config: this.specProvider
          },
        })
      );
    };

    // chain catalog loading and spec loading
    let afterCatalogLoaded = (catalog: Catalog | undefined) => {
      this.catalog = catalog;
      this.initSpecificationProvider(afterSpecificationLoaded);
    };

    this.#initCatalog(afterCatalogLoaded);

    return this;
  }

  #initCatalog(callback: (catalog: Catalog | undefined) => void) {
    let settings = getSettings();
    let me = this;
    if (settings.catalog) {
      $.getJSON(settings.catalog, function (data) {
        callback(new Catalog(data));
      }).fail(function (response) {
        console.error(
          "Sparnatural - unable to load catalog file : " + settings.catalog
        );
        callback(undefined);
      });
    } else {
      // no catalog provided
      callback(undefined);
    }
  }

  initSpecificationProvider(callback: (sp: ISparnaturalSpecification) => void) {
    let settings = getSettings();
    let specProviderFactory = new SparnaturalSpecificationFactory();
    // load only the statistics of the selected endpoints
    specProviderFactory.build(
      settings.src,
      settings.language,
      this.catalog
        ? this.catalog.extractSubCatalog(settings.endpoints)
        : undefined,
      (sp: any) => {
        // call the call back when done
        callback(sp);
      }
    );
  }

  // method is exposed from the HTMLElement
  enablePlayBtn = () => {
    this.submitSection.playBtn.removeLoading();
  };

  // method is exposed from the HTMLElement
  disablePlayBtn = () => {
    this.submitSection.playBtn.disable();
  };

  setQuiet(quiet: boolean) {
    this.actionStore.quiet = quiet;
  }

  isEmpty() {
    return (
      this.BgWrapper.componentsList.rootGroupWrapper.criteriaGroup
        .startClassGroup.startClassVal?.type == null
    );
  }

  #initLang() {
    if (getSettings().language === "fr") {
      I18n.init("fr");
    } else {
      I18n.init("en");
    }
  }

  /**
   * @returns A map with the max variable index for each type, based on the variables used in the current SPARQL query. 
   */
  getMaxVariableIndexByTypes(): Map<string, number> {
    let maxVariableIndexPerType = new Map<string, number>();

    this.BgWrapper.componentsList.rootGroupWrapper.traversePostOrder(
      (grpWrapper) => {

        // generic counting function to extract the index of a variable and update the max index for its type
        let processTypeVar = (type:string, variable:string) => {
          if(type && variable) {
            // if a variable does not match this pattern, it means it will not be counted
            // which is OK, as there is no risk of collision with the generated variables that always have an index
            if(variable.match(/_(\d+)$/)) {
              let index = parseInt(variable.match(/_(\d+)$/)![1]);

              if(maxVariableIndexPerType.has(type) && maxVariableIndexPerType.get(type)! < index) {
                maxVariableIndexPerType.set(type, index);
              } else if(!maxVariableIndexPerType.has(type)) {
                maxVariableIndexPerType.set(type, index);
              }
            }
            
            // also check the base variable without index, in case there is only one variable of this type which does not have an index
            let baseVar = Model.getSparqlVariableNameFromUri(type);
            if(variable === baseVar && !maxVariableIndexPerType.has(type)) {
              maxVariableIndexPerType.set(type, 1);
            }
          }
        }

        // count the variable only if it is the very first
        if (grpWrapper.depth === 0 && grpWrapper.order === 0) {
          processTypeVar(
            grpWrapper.criteriaGroup.startClassGroup?.startClassVal.type,
            grpWrapper.criteriaGroup.startClassGroup?.startClassVal.variable
          );
        }

        // always count the end class group
        processTypeVar(
            grpWrapper.criteriaGroup.endClassGroup?.endClassVal.type,
            grpWrapper.criteriaGroup.endClassGroup?.endClassVal.variable
        );

        // always count the object property group
        processTypeVar(
          grpWrapper.criteriaGroup.objectPropertyGroup?.objectPropVal.type,
          grpWrapper.criteriaGroup.objectPropertyGroup?.objectPropVal.variable
        );
      }
    );

    return maxVariableIndexPerType;
  }

  generateNewVariableName(type: string): string {
    let maxVariableIndexPerType = this.getMaxVariableIndexByTypes();
    let currentTypeIndex = maxVariableIndexPerType.get(type) || 0;

    if(currentTypeIndex === 0) {
      // if first variable of this type don't add the index to have more readable variable names when there's only one of each type,
      // e.g ?Country instead of ?Country_1
      return `${Model.getSparqlVariableNameFromUri(type)}`;
    } else {
      return `${Model.getSparqlVariableNameFromUri(type)}_${currentTypeIndex + 1}`;
    }
  }

}
export default SparnaturalComponent;
