import { Term } from "@rdfjs/types/data-model";

/**
 * What a widget hands its datasource : the graph pattern of the query being edited, and
 * the variable of that query the pattern hangs on.
 */
export interface QueryPattern {
    pattern: string;
    subjectVariable: string;
}

/**
 * This file contains interfaces and classes for building SPARQL queries
 * for various operations such as listing, autocompleting, and tree structures.
 * It includes template-based query builders that can be customized with specific parameters.
 */

/**
 * Injects the pattern of the query being edited into a datasource query. The template
 * subject, written $this or ?this, takes the name of the variable the pattern hangs on,
 * so that both halves join. Without a pattern, $this stays a plain SPARQL variable and
 * the template is returned untouched.
 */
function injectQueryPattern(sparql: string, queryPattern?: QueryPattern): string {
    // a template without $this could not be joined to the pattern : injecting would only
    // make the endpoint combine two unrelated halves
    const joinable = !!queryPattern?.pattern && !!queryPattern.subjectVariable && /[?$]this\b/.test(sparql);

    if (!joinable) return sparql;

    const variable = "?" + queryPattern.subjectVariable;

    // the pattern goes right before the first triple written on the subject.
    // Anchoring on $this rather than on the first brace matters : in the templates that
    // count, the first brace opens the outer query, where the subject of the inner one is
    // unknown. And only an occurrence starting a line is a triple : the first one can sit
    // inside a COUNT(), which is not a place to paste a graph pattern into.
    let pasted = false;
    return sparql.replace(/[?$]this\b/g, (match, offset: number, whole: string) => {
        const lineStart = whole.lastIndexOf("\n", offset - 1) + 1;
        const indent = whole.slice(lineStart, offset);

        if (pasted || !/^[ \t]*$/.test(indent)) return variable;

        pasted = true;
        return queryPattern.pattern + "\n" + indent + variable;
    });
}

/**
 * Interface for building SPARQL queries to retrieve labels (or other values) for a given URI in a specific predicate.
 */
export interface SinglePredicateSparqlQueryBuilderIfc  {

    /**
     * Builds a single column query with the value of the given predicate for the given URI, in the given language (or default language if not available)
     */
    buildSparqlQuery(
        uri:string,
        predicate:string,
        language: any,
        defaultLanguage: any
    ):string;

}

export class SinglePredicateSparqlQueryBuilder implements SinglePredicateSparqlQueryBuilderIfc {

    sparqlPostProcessor: any;

    constructor(
        sparqlPostProcessor: any
    ) {
        this.sparqlPostProcessor = sparqlPostProcessor;
    }

    buildSparqlQuery(
        uri:string,
        predicate:string,
        language: any,
        defaultLanguage: any
    ):string {
        // Fetch <predicate> value(s) for <uri> in the wanted/default/no-tag
        // language ; predicate may be a path, values are concatenated.
        var sparql = `
SELECT ?uri (GROUP_CONCAT(DISTINCT STR(?value) ; separator=", ") AS ?label)
WHERE {
  BIND(<${uri}> AS ?uri)
  ?uri ${predicate} ?value .
  FILTER(lang(?value) = "" || lang(?value) = "${language}" || lang(?value) = "${defaultLanguage}")
}
GROUP BY ?uri
`;

        sparql = this.sparqlPostProcessor.semanticPostProcess(sparql);
        return sparql;
    }


}


/**
 * Interface for building SPARQL queries to list items based on a domain, predicate, and range (coming from the query), and other attributes from Sparnatural itself
 */
export interface ListSparqlQueryBuilderIfc  {

    buildSparqlQuery(
        domain:string,
        predicate:string,
        range:string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ):string;

}

/**
 * Same for lists, but using a fixed list of values (used when sh:in is present in the SHACL)
 */
export interface ValuesListSparqlQueryBuilderIfc  {

    buildSparqlQuery(
        values:Term[],
        language: any,
        defaultLanguage: any,
        typePath: string
    ):string;

}

export class ListSparqlTemplateQueryBuilder implements ListSparqlQueryBuilderIfc {
    
    queryString: string;
    sparqlPostProcessor: any;

    constructor(
        queryString: string,
        sparqlPostProcessor: any,

    ) {
        this.queryString = queryString;
        this.sparqlPostProcessor = sparqlPostProcessor;
    }

    buildSparqlQuery(
        domain: string,
        property: string,
        range: string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ): string {
        var reDomain = new RegExp("\\$domain", "g");
        var reProperty = new RegExp("\\$property", "g");
        var reRange = new RegExp("\\$range", "g");
        var reLang = new RegExp("\\$lang", "g");
        var reDefaultLang = new RegExp("\\$defaultLang", "g");
        var reType = new RegExp("\\$type", "g");

        var sparql = this.queryString
          .replace(reDomain, "<" + domain + ">")
          .replace(reProperty, "<" + property + ">")
          .replace(reRange, "<" + range + ">")
          .replace(reLang, "'" + language + "'")
          .replace(reDefaultLang, "'" + defaultLanguage + "'")
          .replace(reType, typePath);

        sparql = injectQueryPattern(sparql, queryPattern);

        sparql = this.sparqlPostProcessor.semanticPostProcess(sparql);

        return sparql;
    }

}



export class ValuesListSparqlTemplateQueryBuilder implements ValuesListSparqlQueryBuilderIfc {
    
    queryString: string;
    sparqlPostProcessor: any;

    constructor(
        queryString: string,
        sparqlPostProcessor: any,

    ) {
        this.queryString = queryString;
        this.sparqlPostProcessor = sparqlPostProcessor;
    }

    buildSparqlQuery(
        values:Term[],        
        language: any,
        defaultLanguage: any,
        typePath: string
    ): string {
        var reValues = new RegExp("\\$values", "g");
        var reLang = new RegExp("\\$lang", "g");
        var reDefaultLang = new RegExp("\\$defaultLang", "g");
        var reType = new RegExp("\\$type", "g");

        // turn the values into their corresponding string representation in SPARQL
        var stringValues = values.map((value: Term) => {
            if (value.termType === 'NamedNode') {
                return "<"+value.value+">"; // NamedNode is a URI
            } else if (value.termType === 'Literal') {
                // For literals, we need to include the language tag or datatype
                if (value.language) {
                    return `"${value.value}"@${value.language}`; // Literal with language tag
                } else if (value.datatype) {
                    return `"${value.value}"^^<${value.datatype.value}>`; // Literal with datatype
                } else {
                    return `"${value.value}"`; // Plain literal
                }
            } else {
                throw new Error(`Unsupported term type: ${value.termType}`);
            }
        }).join(" ");
    
        var sparql = this.queryString
          .replace(reValues, stringValues)
          .replace(reLang, "'" + language + "'")
          .replace(reDefaultLang, "'" + defaultLanguage + "'")
          .replace(reType, typePath);
          
        sparql = this.sparqlPostProcessor.semanticPostProcess(sparql);

        return sparql;
    }

}



export interface AutocompleteSparqlQueryBuilderIfc  {

    buildSparqlQuery(
        domain:string,
        predicate:string,
        range:string,
        key:string,
        language: any,
        defaultLang : any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ):string;

}

export class AutocompleteSparqlTemplateQueryBuilder implements AutocompleteSparqlQueryBuilderIfc {
    
    queryString: string;
    sparqlPostProcessor: { semanticPostProcess: (sparql:string)=>string };

    constructor(
        queryString: string,
        sparqlPostProcessor: { semanticPostProcess: (sparql:string)=>string },

    ) {
        this.queryString = queryString;
        this.sparqlPostProcessor = sparqlPostProcessor;
    }

    buildSparqlQuery(
        domain: string,
        property: string,
        range: string,
        key:string,
        language: any,
        defaultLanguage : any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ): string {
        var reDomain = new RegExp("\\$domain", "g");
        var reProperty = new RegExp("\\$property", "g");
        var reRange = new RegExp("\\$range", "g");
        var reKey = new RegExp("\\$key", "g");
        var reLang = new RegExp("\\$lang", "g");
        var reDefaultLang = new RegExp("\\$defaultLang", "g");
        var reType = new RegExp("\\$type", "g");

        var sparql = this.queryString
          .replace(reDomain, "<" + domain + ">")
          .replace(reProperty, "<" + property + ">")
          .replace(reRange, "<" + range + ">")
          .replace(reKey, "" + key + "")
          .replace(reLang, "'" + language + "'")
          .replace(reDefaultLang, "'" + defaultLanguage + "'")
          .replace(reType, typePath);

        sparql = injectQueryPattern(sparql, queryPattern);

        sparql = this.sparqlPostProcessor.semanticPostProcess(sparql);

        return sparql;
    }

}



export interface TreeSparqlQueryBuilderIfc  {

    buildRootsSparqlQuery(
        domain:string,
        predicate:string,
        range:string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ):string;

    buildChildrenSparqlQuery(
        node:string,
        domain:string,
        predicate:string,
        range:string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ):string;

}


export class TreeSparqlTemplateQueryBuilder implements TreeSparqlQueryBuilderIfc {
    
    rootsQueryString: string;
    childrenQueryString: string;
    sparqlPostProcessor: any;

    constructor(
        rootsQueryString: string,
        childrenQueryString: string,
        sparqlPostProcessor: any,
    ) {
        this.rootsQueryString = rootsQueryString;
        this.childrenQueryString = childrenQueryString;
        this.sparqlPostProcessor = sparqlPostProcessor;
    }

    buildRootsSparqlQuery(
        domain: string,
        property: string,
        range: string,        
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ): string {
        return this.#buildSparql(this.rootsQueryString,null,domain,property,range,language,defaultLanguage,typePath,queryPattern);
    }

    buildChildrenSparqlQuery(
        node:string,
        domain: string,
        property: string,
        range: string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        // graph pattern of the query being edited, injected in the datasource query
        queryPattern?: QueryPattern
    ): string {
        return this.#buildSparql(this.childrenQueryString,node,domain,property,range,language,defaultLanguage,typePath,queryPattern);
    }

    #buildSparql(
        queryString: string,
        node:string|null,
        domain: string,
        property: string,
        range: string,
        language: any,
        defaultLanguage: any,
        typePath: string,
        queryPattern?: QueryPattern
    ) {
        var reDomain = new RegExp("\\$domain", "g");
        var reProperty = new RegExp("\\$property", "g");
        var reRange = new RegExp("\\$range", "g");
        var reLang = new RegExp("\\$lang", "g");
        var reDefaultLang = new RegExp("\\$defaultLang", "g");
        var reType = new RegExp("\\$type", "g");
    
        var sparql = queryString
          .replace(reDomain, "<" + domain + ">")
          .replace(reProperty, "<" + property + ">")
          .replace(reRange, "<" + range + ">")
          .replace(reLang, "'" + language + "'")
          .replace(reDefaultLang, "'" + defaultLanguage + "'")
          .replace(reType, typePath);
          
          if (node != null) {
            var reNode = new RegExp("\\$node", "g");
            sparql = sparql.replace(reNode, "<" + node + ">");
          }

        // nodes are never removed, the tree must stay navigable : in templates counting on
        // $this, the pattern only brings to 0, so disables, the nodes leading to no result
        sparql = injectQueryPattern(sparql, queryPattern);

        sparql = this.sparqlPostProcessor.semanticPostProcess(sparql);

        return sparql;        
    }

}
